import 'dart:convert';

/// 장치 이름 변경
class Device {
  static final _allowed = RegExp(r'^[A-Za-z0-9_-]+$');
  String name;
  Device(this.name);

  /// 영문 · 숫자 · - _ 만, 16바이트 이하 (장비가 긴 이름 · 한글을 잘라 저장함)
  void rename(String newName) {
    if (!_allowed.hasMatch(newName) || utf8.encode(newName).length > 16) {
      throw ArgumentError('장치 이름은 영문 · 숫자 · - _ 만, 16바이트 이하');
    }
    name = newName;
  }
}

