import 'dart:convert';
import 'dart:io';

import 'package:pub_semver/pub_semver.dart';

import 'fw_update.dart';

enum Compat { ok, blocked, unknown }

/// 펌웨어 호환표 (assets/fw_compat.json): 펌웨어 버전 → 보드 종류별 허용 현재 버전 범위
class CompatChecker {
  final Map<String, dynamic> table;
  CompatChecker(this.table);

  factory CompatChecker.load([String path = 'assets/fw_compat.json']) =>
      CompatChecker(jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>);

  Compat check(Board board, FirmwareFile file) {
    final rule = (table[file.version] as Map?)?[board.type] as String?;
    if (rule == null) return Compat.blocked;
    if (board.version.isEmpty) return Compat.unknown; // 구형 보드는 버전을 주지 않음
    return VersionConstraint.parse(rule).allows(Version.parse(board.version))
        ? Compat.ok
        : Compat.blocked;
  }
}

