import 'compat_check.dart';

/// 펌웨어 업데이트
class Board {
  final String type;
  final String version;
  Board(this.type, this.version);
}

class FirmwareFile {
  final String version;
  FirmwareFile(this.version);
}

class FwUpdater {
  final CompatChecker? checker;
  FwUpdater([this.checker]);

  /// 업데이트를 시작하고 결과 버전을 돌려준다.
  /// 호환표에 없으면 막고, 보드 버전을 알 수 없으면 엔지니어가 확인한 뒤 force 로 진행
  String start(Board board, FirmwareFile file, {bool force = false}) {
    final r = checker?.check(board, file) ?? Compat.ok;
    if (r == Compat.blocked) throw StateError('호환되지 않는 펌웨어');
    if (r == Compat.unknown && !force) throw StateError('확인 불가: 보드 버전을 알 수 없음');
    return file.version;
  }
}

