import '../config.dart';

/// 점검 로그 저장 · 보관
class LogStore {
  final int keepDays;
  final int maxEntries;
  final List<(DateTime, String)> entries = [];

  LogStore({this.keepDays = 30, this.maxEntries = 1000});

  /// 보관 기간은 assets/config.json 의 log_keep_days
  factory LogStore.fromConfig(Config c) =>
      LogStore(keepDays: c.values['log_keep_days'] as int? ?? 30);

  /// 저장 한도를 넘으면 가장 오래된 로그부터 지우고 저장
  void write(String message, [DateTime? at]) {
    if (entries.length >= maxEntries) entries.removeAt(0);
    entries.add((at ?? DateTime.now(), message));
  }

  /// 보관 기간이 지난 로그 삭제
  void cleanup([DateTime? now]) {
    final limit = (now ?? DateTime.now()).subtract(Duration(days: keepDays));
    entries.removeWhere((e) => e.$1.isBefore(limit));
  }
}

