import 'package:inspection_tool/device/device_name.dart';
import 'package:test/test.dart';

void main() {
  test('장치 이름 변경', () {
    final d = Device('EL-01')..rename('EL-02');
    expect(d.name, 'EL-02');
  });

  test('한글 · 16바이트 초과 이름은 막음', () {
    expect(() => Device('EL-01').rename('승강기1'), throwsArgumentError);
    expect(() => Device('EL-01').rename('A' * 17), throwsArgumentError);
  });
}

