import 'package:inspection_tool/fwupdate/compat_check.dart';
import 'package:inspection_tool/fwupdate/fw_update.dart';
import 'package:test/test.dart';

void main() {
  final up = FwUpdater(CompatChecker.load());

  test('업데이트 후 파일 버전으로 바뀜', () {
    expect(FwUpdater().start(Board('main', '1.0.0'), FirmwareFile('1.1.0')), '1.1.0');
  });

  test('호환 범위 안이면 진행', () {
    expect(up.start(Board('main', '1.0.3'), FirmwareFile('1.1.0')), '1.1.0');
  });

  test('범위 밖 · 호환표에 없는 보드는 막음', () {
    expect(() => up.start(Board('main', '0.9.0'), FirmwareFile('1.1.0')), throwsStateError);
    expect(() => up.start(Board('panel', '1.0.0'), FirmwareFile('1.1.0')), throwsStateError);
  });

  test('버전을 모르면 확인 후 force 로만 진행', () {
    expect(() => up.start(Board('main', ''), FirmwareFile('1.1.0')), throwsStateError);
    expect(up.start(Board('main', ''), FirmwareFile('1.1.0'), force: true), '1.1.0');
  });
}

