import 'package:inspection_tool/config.dart';
import 'package:inspection_tool/log/log_store.dart';
import 'package:test/test.dart';

void main() {
  test('보관 기간이 지난 로그 삭제', () {
    final now = DateTime(2026, 11, 1);
    final s = LogStore()
      ..write('old', now.subtract(const Duration(days: 31)))
      ..write('new', now);
    s.cleanup(now);
    expect(s.entries.map((e) => e.$2), ['new']);
  });

  test('보관 기간을 설정값에서 읽음', () {
    expect(LogStore.fromConfig(Config({'log_keep_days': 7})).keepDays, 7);
  });

  test('저장 한도를 넘으면 오래된 로그부터 지움', () {
    final s = LogStore(maxEntries: 2)..write('1')..write('2')..write('3');
    expect(s.entries.map((e) => e.$2), ['2', '3']);
  });
}
